<?= $this->section('scripts') ?><script>$(function(){$('.edit-record').on('click',function(){$('#recordForm [name=id]').val($(this).data('id'));$('#recordForm [name=master_type]').val($(this).data('type'));$('#recordName').val($(this).data('name'));$('#recordCode').val($(this).data('code')||'');$('#recordAmount').val($(this).data('amount')||'');$('#recordDescription').val($(this).data('description')||'');$('#recordStatus').val($(this).data('status')||'1');$('#recordModal').modal('show');});$('#recordForm').on('submit',function(e){e.preventDefault();ajaxRequest({url:'<?= base_url('admin/configuration/masters/save') ?>',data:$(this).serialize(),success:function(r){if(r.status)reload_page(500);else showError(r.msg);}});});$('.delete-record').on('click',function(){if(confirm('Delete this record?'))ajaxRequest({url:'<?= base_url('admin/configuration/masters/delete') ?>/'+$(this).data('id'),data:{csrf_rtn:$('input[name=csrf_rtn]').val(),master_type:$(this).data('type')},success:function(r){if(r.status)reload_page(500);else showError(r.msg);}});});});</script><?= $this->endSection() ?>
